//
// UNDER THE HOOD: the tables of every control of the open-source engines (generated by tools/gen_hood_tables.py from the
// engines' own control lists) and the "pins": the controls you moved. A pin is stored as "engine.id" -> value, in the
// engine's own units. Nothing is stored for a control you have not moved, so the other pages sound exactly as before.
#pragma once
#include <initializer_list>
#include <map>
#include <string>
#include <vector>

namespace matter::hood
{
struct HoodControlDef
{
    const char *engine, *group, *id, *upstream, *ours;
    char kind;                       // 'f' decimal, 'i' whole number, 'b' on/off, 'c' a choice
    float lo, hi, upDef, matDef, mid;
    const char *unit, *choices, *call, *tip, *linked;
};
struct HoodEngineDef { const char *key, *title, *page, *source; };

using Pins = std::map<std::string, float>;

int count();
const HoodControlDef& def (int i);
int indexOf (const std::string& key);                 // "engine.id" -> table index, -1 if none
std::string keyOf (const HoodControlDef& d);          // "engine.id"
int engineCount();
const HoodEngineDef& engine (int i);
int engineIndex (const std::string& key);             // -1 if none
std::vector<std::string> choicesOf (const HoodControlDef& d);

// the controls that are read on the audio thread (Pertylizer, Box2D and the PM-Synth voices BOUNCE strikes) have a slot
constexpr int kLiveSlots = 64;
struct LivePins
{
    float v[kLiveSlots] {};
    bool on[kLiveSlots] {};
    bool any = false;
    float pick (int slot, float normal) const noexcept { return on[slot] ? v[slot] : normal; }
};
int liveSlot (int tableIndex);                        // -1 if the control is not read live
int liveSlotOf (const char* engine, const char* id);  // -1 if none
int liveBase (const char* engine);                    // the first slot of an engine (its controls follow in table order)
const HoodControlDef& liveDef (int slot);

// pins that matter to a render step (so changing one starts a new render)
inline bool samePins (const Pins& a, const Pins& b, std::initializer_list<const char*> engines)
{
    auto pick = [&] (const Pins& p)
    {
        Pins r;
        for (auto& kv : p) for (auto* e : engines) { const std::string pre = std::string (e) + "."; if (kv.first.compare (0, pre.size(), pre) == 0) r.insert (kv); }
        return r;
    };
    return pick (a) == pick (b);
}
inline bool hasEngine (const Pins& p, const char* engine)
{
    const std::string pre = std::string (engine) + ".";
    for (auto& kv : p) if (kv.first.compare (0, pre.size(), pre) == 0) return true;
    return false;
}
inline float pinOr (const Pins& p, const char* key, float fallback)
{
    auto it = p.find (key);
    return it != p.end() ? it->second : fallback;
}
}
